command:
install -m 0600 -o root -g root /etc/nginx/nginx.conf /etc/nginx/nginx.conf.pre-https-rotation
cat > /etc/nginx/nginx.conf <<'NGINX_MAIN'
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log notice;
pid /run/nginx.pid;

include /usr/share/nginx/modules/*.conf;

events {
    worker_connections 1024;
}

http {
    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for"';
    access_log /var/log/nginx/access.log main;
    sendfile on;
    tcp_nopush on;
    keepalive_timeout 65;
    types_hash_max_size 4096;
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    include /etc/nginx/conf.d/*.conf;
}
NGINX_MAIN
cat > /etc/nginx/conf.d/https-8443.conf <<'NGINX_TLS'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name _;
    server_tokens off;

    ssl_certificate /etc/pki/https-rotation/server.crt;
    ssl_certificate_key /etc/pki/https-rotation/server.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers PROFILE=SYSTEM;
    ssl_session_cache shared:TLS:1m;
    ssl_session_timeout 10m;
    ssl_session_tickets off;

    default_type text/plain;
    return 200 "node1 HTTPS certificate rotation is healthy\n";
}
NGINX_TLS
chmod 0644 /etc/nginx/nginx.conf /etc/nginx/conf.d/https-8443.conf
chown root:root /etc/nginx/nginx.conf /etc/nginx/conf.d/https-8443.conf
restorecon /etc/nginx/nginx.conf /etc/nginx/conf.d/https-8443.conf
nginx -t
sha256sum /etc/nginx/nginx.conf /etc/nginx/conf.d/https-8443.conf
stat -c '%a %U:%G %C %n' /etc/nginx/nginx.conf /etc/nginx/conf.d/https-8443.conf /etc/nginx/nginx.conf.pre-https-rotation

